const qr=()=>{let s=7,h="";const Fi=[[0,0],[14,0],[0,14]],fin=(x,y)=>Fi.some(([a,c])=>{const u=x-a,w=y-c;return u>=0&&u<7&&w>=0&&w<7&&(u%6==0||w%6==0||(u>1&&u<5&&w>1&&w<5))}),gap=(x,y)=>Fi.some(([a,c])=>x>=a-1&&x<a+8&&y>=c-1&&y<c+8);for(let y=0;y<21;y++)for(let x=0;x<21;x++){s=(s*1103515245+12345)&0x7fffffff;h+=`<b class="${fin(x,y)||(!gap(x,y)&&s%3==0)?"k":""}"></b>`}return`<div class="qr" aria-label="QR">${h}</div>`};
